package app.moire.anniversary;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.text.*;import android.text.style.ForegroundColorSpan;import android.webkit.JavascriptInterface;import android.widget.RemoteViews;import org.json.*;import java.util.*;
public class MoireWidget extends AppWidgetProvider {
 static final String PREF="moire_v23",CHANNEL="moire_upcoming_v24";
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){refresh(c);}
 @Override public void onDeleted(Context c,int[] ids){refresh(c);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())||Intent.ACTION_DATE_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction())||Intent.ACTION_TIME_CHANGED.equals(i.getAction())){refresh(c);MoireAlarm.scheduleAll(c);}}
 static JSONArray rows(JSONObject o,String k){JSONArray a=o==null?null:o.optJSONArray(k);return a==null?new JSONArray():a;}
 static String dday(int d){return d==0?"D-DAY":d>0?"D-"+d:"D+"+(-d);}
 static String lines(JSONArray a,int max){StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(max,a.length());i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;if(b.length()>0)b.append("\n");b.append(x.optString("category","🎉")).append(" ").append(x.optString("name")).append("  ").append(dday(x.optInt("days")));}return b.length()==0?"MOIRE에서 기념일을 선택하세요":b.toString();}
 static CharSequence styled(JSONArray a,int max){SpannableStringBuilder b=new SpannableStringBuilder();for(int i=0;i<Math.min(max,a.length());i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;if(b.length()>0)b.append("\n");int start=b.length();b.append(x.optString("category","🎉")).append(" ").append(x.optString("name"));b.setSpan(new ForegroundColorSpan(Color.BLACK),start,b.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);b.append("  ");start=b.length();b.append(dday(x.optInt("days")));b.setSpan(new ForegroundColorSpan(Color.RED),start,b.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}return b;}
 static void refresh(Context c){try{JSONObject data=new JSONObject(c.getSharedPreferences(PREF,0).getString("data","{}"));AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,MoireWidget.class));JSONObject widgets=data.optJSONObject("widgets");for(int id:ids){JSONArray list=rows(widgets,String.valueOf(id));RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.moire_widget);v.setTextViewText(R.id.widget_text,lines(list,5));Intent intent=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_root,pi);manager.updateAppWidget(id,v);}NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"MOIRE 기념일 목록",NotificationManager.IMPORTANCE_LOW));JSONArray list=rows(data,"notifications");nm.cancel(2301);if(list.length()==0)return;Intent launch=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,2301,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(R.mipmap.ic_launcher).setContentTitle("MOIRE").setContentText(styled(list,1)).setStyle(new Notification.BigTextStyle().bigText(styled(list,3))).setContentIntent(pi).setOngoing(true).setShowWhen(false).build();nm.notify(2301,n);}catch(Exception e){android.util.Log.e("MOIRE","refresh",e);}}
 public static class Bridge {Context c;Bridge(Context c){this.c=c;}@JavascriptInterface public void update(String json){try{JSONObject o=new JSONObject(json);c.getSharedPreferences(PREF,0).edit().putString("data",json).apply();JSONArray alarms=rows(o,"alarms");new Handler(Looper.getMainLooper()).post(()->{refresh(c);MoireAlarm.sync(c,alarms);});}catch(Exception e){android.util.Log.e("MOIRE","update",e);}}@JavascriptInterface public String getWidgetIds(){try{return new JSONArray(AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,MoireWidget.class))).toString();}catch(org.json.JSONException e){return "[]";}}@JavascriptInterface public void testAlarm(){new Handler(Looper.getMainLooper()).post(()->MoireAlarm.test(c));}@JavascriptInterface public void chooseSound(){if(c instanceof MainActivity)new Handler(Looper.getMainLooper()).post(()->((MainActivity)c).chooseSound());}}
}
